 resourcePanel('分组考勤汇总',factoryReportTable(['小组','全天','半天','缺勤 / 请假'],f.attendance_groups.map(g=>`<tr><td>${esc(g.group_name)}</td><td>${g.full}</td><td>${g.half}</td><td>${g.absent}</td></tr>`).join('')))+
 resourcePanel('原辅料领用',factoryReportTable(['物料','库房','数量','领用用途','经办人'],f.issues.map(e=>`<tr><td>${esc(e.material_name)}</td><td>${esc(e.warehouse_name)}</td><td>${num(e.qty)}${esc(e.unit)}</td><td>${esc(e.note)}</td><td>${esc(e.handler)}</td></tr>`).join('')))+soyAnalysisBlock(f.soybean_analysis)+resourcePanel('原辅料库存分析',factoryReportTable(['物料','数量','预警线','状态'],f.materials.map(i=>`<tr><td>${esc(i.name)}</td><td>${num(i.id==='RM-SOY'?Number(i.qty)/1000:i.qty)}${esc(i.id==='RM-SOY'?'吨':i.unit)}</td><td>${num(i.id==='RM-SOY'?Number(i.reorder_qty)/1000:i.reorder_qty)}</td><td>${i.low_stock?factoryAlert('低库存'):'正常'}</td></tr>`).join('')))+resourcePanel('生产换算依据',factorySettingsSummary(f.settings))+'</details>';
