function factoryShowNotice(r){openDialog('排班通知 · 可复制到微信群',`<p class="form-help">包含各组人员、上班时间及相对昨天的调整，不包含下班时间。</p><label class="field">通知文字<textarea id="factory-notice-text" rows="14" readonly>${esc(r.notice||'请先确认当天排班')}</textarea></label>`,'ATTENDANCE · 通知文字','<button class="button" data-act="close">关闭</button><button class="button primary" data-factory-copy-notice>复制通知</button>');}
function factoryDeleteRecord(kind,options={}){
 if(!factoryAdmin()){notify('仅管理员可以删除登记记录');return;}
 if(kind==='attendance-month'&&options.recordCount==null){const origin=page,month=options.month||attendanceMonth||factoryDate().slice(0,7);api('/api/attendance-month-count?'+new URLSearchParams({month,employee_id:options.employeeId||''})).then(result=>{if(page===origin)factoryDeleteRecord(kind,{...options,month,recordCount:result.record_count});}).catch(error=>notify(error.message));return;}
 if(['attendance','schedule'].includes(kind)&&factoryData().attendance_deferred&&!cachedAttendanceDay()){withAttendanceDay(()=>factoryDeleteRecord(kind,options));return;}

 let title='',details='',attrs='';
 if(kind==='attendance-month'){
  const month=options.month||attendanceMonth||factoryDate().slice(0,7),name=options.name||'该员工',days=options.recordCount;
  title='删除整月考勤 · '+name;
  attrs=`data-kind="attendance-month" data-employee-id="${esc(options.employeeId||'')}" data-month="${esc(month)}"`;
  details=`<p class="callout warning">将删除 <b>${esc(name)}</b> 在 ${esc(month)} 的整月考勤（已有 ${days} 天记录）；同一天其他人员的考勤保留，删除后不能恢复。</p>`;
 }else{
  const current=kind==='schedule'?daySchedule():dayAttendance();const record=current?.id===options.id?current:(kind==='schedule'?(factoryData().schedules||[]):factoryData().attendance).find(r=>r.id===options.id);
  if(!record){notify('记录不存在，请刷新后重试');return;}
  const day=record.business_date,scope=kind==='attendance'?(options.scope||personnelScope()):'';
  const entries=kind==='attendance'?(record.entries||[]).filter(e=>personnelType(factoryData().employees.find(p=>p.id===e.employee_id)||e)===scope):(record.entries||[]);
  title=(kind==='schedule'?'删除排班 · ':'删除考勤 · ')+day;
  attrs=`data-kind="${kind}" data-id="${esc(record.id)}" data-version="${Number(record.version)||0}"${scope?` data-scope="${esc(scope)}"`:''}`;
  details=`<p class="callout warning">将删除 <b>${esc(day)}</b> 的${kind==='schedule'?'当天分组排班':'当天实际考勤'}，涉及 ${entries.length} 人；删除后不能恢复，审计记录保留原内容。</p>`;
 }
 openDialog(title,`<form id="factory-delete-form" ${attrs} data-request-key="${erpRequestKey()}"><div class="form-grid">${details}${factoryField('删除原因','reason','text','','required maxlength="500" placeholder="例如：重复登记、人员录错、日期选错"')}<p class="help-text wide">如该月工资已确认，系统会拒绝删除；请先在员工工资中撤回工资确认。</p></div></form>`,'FACTORY · 管理员删除','<button class="button" data-act="close">取消</button><button class="button danger" data-factory-delete-confirm>确认删除</button>');
}
async function factoryDeleteConfirmed(){
 const f=$('#factory-delete-form');if(!f||!f.reportValidity())return;
 const b={kind:f.dataset.kind,reason:f.elements.reason.value,request_key:f.dataset.requestKey};
 if(f.dataset.id)b.id=f.dataset.id;
 if(f.dataset.version)b.version=Number(f.dataset.version);
 if(f.dataset.scope)b.scope=f.dataset.scope;
 if(f.dataset.employeeId)b.employee_id=f.dataset.employeeId;
 if(f.dataset.month)b.month=f.dataset.month;
 await perform(async()=>{await api('/api/factory/delete',b);busy=false;closeDialog();factoryReports.clear();await refresh();notify('登记记录已删除');});
}
document.addEventListener('click',e=>{
 const work=e.target.closest('[data-factory-work-tab]');if(work){requestPageTransition(()=>{factoryWorkTab=work.dataset.factoryWorkTab;render();});return;}
 if(e.target.closest('[data-factory-follow=beans]')){requestPageTransition(()=>{factoryWorkTab='beans';goto('factory',{keepTabs:true});});return;}
 if(e.target.closest('[data-attendance-fill-start]')){const value=$('#attendance-default-start').value;if(!value){notify('请先填写默认上班时间');return;}collectAttendanceEditor();localStorage.setItem('erp-attendance-default-start',value);attendanceEditor.groups.forEach(g=>g.start_time=value);paintAttendanceEditor();return;}
 const chip=e.target.closest('[data-people-filter]');if(chip){const scope=chip.dataset.peopleScope,kind=chip.dataset.peopleFilter,value=chip.dataset.value||'';if(scope==='editor'){collectAttendanceEditor();if(kind==='reset'){attendanceEditGroup='';attendanceEditStatus='all';attendanceEditSearch='';}else if(kind==='group')attendanceEditGroup=value;else if(kind==='status')attendanceEditStatus=value;paintAttendanceEditor();}else{if(scope==='employee'){if(kind==='reset'){employeeGroup='';employeeType='';employeeStatus='all';employeeSearch='';}else if(kind==='type')employeeType=value;else if(kind==='group')employeeGroup=value;else if(kind==='status')employeeStatus=value;else if(kind==='view'){employeeView=value;employeeSearch='';employeeStatus='all';}}else if(scope==='attendance'){if(kind==='reset'){attendanceGroup='';attendanceStatus='all';attendanceSearch='';}else if(kind==='group')attendanceGroup=value;else if(kind==='status')attendanceStatus=value;}render();}return;}
 const remove=e.target.closest('[data-factory-delete]');if(remove){factoryDeleteRecord(remove.dataset.factoryDelete,{id:remove.dataset.id,scope:remove.dataset.scope,employeeId:remove.dataset.employeeId,month:remove.dataset.month,name:remove.dataset.name});return;}
 const b=e.target.closest('[data-factory-act]');if(b){const act=b.dataset.factoryAct;if(act==='issue'){factoryWorkTab='beans';render();return;}else if(act==='copy-attendance'){const day=factoryDate(),yesterday=new Date(new Date(day+'T12:00').getTime()-86400000).toLocaleDateString('sv-SE');if(!cachedAttendanceDay(yesterday)){notify('请先完成昨日分组读取后再沿用');return;}factoryOpenForm('schedule',daySchedule(day)?.id||'',{copy:scheduleSource(yesterday)});}else if(act==='notice')showAttendanceNotice(b.dataset.id);else factoryOpenForm(act,b.dataset.id,{focusEmployee:b.dataset.focusEmployee,personType:b.dataset.personType});}
 if(e.target.closest('[data-factory-save]'))factorySave().catch(err);if(e.target.closest('[data-factory-confirm]'))factorySave(true).catch(err);
 if(e.target.closest('[data-factory-delete-confirm]'))factoryDeleteConfirmed().catch(err);
 if(e.target.closest('[data-factory-copy-notice]')){const t=$('#factory-notice-text'),manual=()=>{t.focus();t.select();t.setSelectionRange(0,t.value.length);notify('请长按复制已选中的通知文字，可粘贴到微信群');};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t.value).then(()=>notify('通知文字已复制，可粘贴到微信群')).catch(manual);else manual();}
 if(e.target.closest('[data-factory-reload]')){factoryReports.clear();refresh().catch(err);}
});
document.addEventListener('change',e=>{
 if(e.target.id==='attendance-default-start')localStorage.setItem('erp-attendance-default-start',e.target.value);
 if(e.target.id==='factory-date'){if(e.target.type==='month')factoryMonth=e.target.value;else factoryDay=e.target.value;render();}
 if(e.target.id==='factory-employee-group'){employeeGroup=e.target.value;render();}
 if(e.target.closest('#factory-form')&&e.target.dataset.attendanceField){const field=e.target.dataset.attendanceField,id=e.target.closest('[data-attendance-person]').dataset.attendancePerson;collectAttendanceEditor();if(['group_id','status'].includes(field)){if(field==='group_id'&&attendanceEditGroup)attendanceEditGroup=attendanceEditor.entries.find(e=>e.employee_id===id).group_id;paintAttendanceEditor(id,field);}}
 if(e.target.closest('#factory-form')&&$('#factory-form').dataset.kind==='issue'&&['material_id','warehouse_id','business_date'].includes(e.target.name)){const form=$('#factory-form'),mid=form.elements.material_id.value,day=form.elements.business_date.value;if(e.target.name==='material_id'){const ws=factoryIssueWarehouses(mid);form.elements.warehouse_id.innerHTML=factoryOptions(ws,ws[0]?.id);}$('#factory-issue-source').innerHTML=productionSourceSelect(mid,form.elements.warehouse_id.value,'',day);}
 if(e.target.closest('#factory-form')&&e.target.name==='business_date'&&$('#factory-form').dataset.kind==='daily'){const values=issuedBeans(e.target.value);for(const el of $$('[data-issued-beans]'))el.textContent=num(values[el.dataset.issuedBeans])+' kg';}
});
document.addEventListener('submit',e=>{if(e.target.id==='factory-form'){e.preventDefault();factorySave().catch(err);}if(e.target.id==='factory-delete-form'){e.preventDefault();factoryDeleteConfirmed().catch(err);}});
function renderFactoryWarnings(){
 const root=$('#content');
 if(page==='settlements'&&(!data.auth_user||['会计','出纳','管理员'].includes(data.auth_user.role))){
  const visibleOrders=new Set(processingGroups().flatMap(g=>g.orders).map(o=>o.id));
  const rows=(data.weight_analysis||[]).filter(r=>r.alert&&(r.order_ids||[]).some(id=>visibleOrders.has(id)));
  if(rows.length){const panels=$$('.client-sheet',root);let placed=false;for(const panel of panels){const cid=panel.dataset.clientSheet,subset=rows.filter(r=>r.customer_id===cid);if(subset.length){panel.insertAdjacentHTML('beforebegin',`<details class="factory-weight-inline"><summary>⚠ ${esc(subset[0].customer_name)} · 称重异常</summary>${weightAnalysisTable(subset)}</details>`);placed=true;}}if(!placed){const alertHtml=`<details class="factory-weight-inline"><summary>⚠ 称重异常 · ${[...new Set(rows.map(r=>r.customer_name))].map(esc).join('、')}</summary>${weightAnalysisTable(rows)}</details>`;const anchor=root.querySelector('.page-head');(anchor||root).insertAdjacentHTML(anchor?'afterend':'afterbegin',alertHtml);}}
 }
 if(page==='ledger'){
  const alerts=(data.receivable_alerts||[]).filter(r=>r.alert),topAlerts=[...alerts].sort((a,b)=>Number(b.outstanding_cents)-Number(a.outstanding_cents));{const anchor=root.querySelector('.page-head');(anchor||root).insertAdjacentHTML(anchor?'afterend':'afterbegin',`${alerts.length?resourcePanel('历史应收 / 账龄预警',analysisColumns('预警客户当前未收',topAlerts.map(r=>[r.customer_name,Number(r.outstanding_cents)]),'元',`按当前未收从高到低，共 ${topAlerts.length} 户；金额为已复核订单余额。`)+`<details class="factory-weight-inline"><summary>查看预警明细（${topAlerts.length} 户）</summary>${factoryArTable(topAlerts)}</details>`):''}`);}
  for(const row of $$('[data-receivable-order]',root)){const o=data.orders.find(o=>o.id===row.dataset.receivableOrder),a=alerts.find(a=>a.customer_id===o?.customer_id);if(a){row.classList.add('factory-alert-row');row.cells[1].insertAdjacentHTML('beforeend',`<small>${a.amount_alert?'历史应收超额 ':''}${a.days_alert?'超账龄':''}</small>`);}}
 }



}

document.addEventListener('input',e=>{const id=e.target.id;if(id==='factory-employee-search')updateLiveSearch(e,value=>employeeSearch=value);else if(id==='factory-attendance-search')updateLiveSearch(e,value=>attendanceSearch=value);else if(id==='factory-attendance-editor-search')updateLiveSearch(e,value=>{collectAttendanceEditor();attendanceEditSearch=value;},paintAttendanceEditor);});
document.addEventListener('keydown',e=>{if(isTextComposing(e))return;if(e.key==='Enter'&&e.target.id==='factory-attendance-editor-search')e.preventDefault();});

function openSoyQualityDialog(entry){openDialog('大豆批次属性',`<form id="soy-quality-form" data-id="${esc(entry.id)}" data-version="${entry.version}"><p>${esc(entry.material_name)} · ${esc(entry.business_date)} · ${esc(entry.warehouse_name)}</p>${factoryQualityFields()}<label class="field">修改说明<textarea name="note" required maxlength="300" placeholder="如：按供应商检测单补录产地与播种类型"></textarea></label></form>`,'入库批次','<button class="button" data-act="close">取消</button><button class="button primary" data-soy-quality-save>保存属性</button>');for(const field of $$('#soy-quality-form [data-quality-field]'))field.value=entry.quality?.[field.dataset.qualityField]||'';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-soy-quality]');if(b){const lot=b.dataset.soyQuality,entry=resourceData().entries.find(e=>e.id===lot);if(entry)openSoyQualityDialog(entry);else loadMaterialsEntry(lot,b.dataset.soyQualityDate).then(row=>row?openSoyQualityDialog(row):notify('该批次入库流水不在首页缓存中，请到“历史查询”查看')).catch(err);}if(e.target.closest('[data-soy-quality-save]'))saveSoyQuality();});
async function saveSoyQuality(){const f=$('#soy-quality-form');if(!f.reportValidity())return;await perform(async()=>{await api('/api/resources/quality',{id:f.dataset.id,version:Number(f.dataset.version),revision:resourceData().revision,quality:Object.fromEntries($$('[data-quality-field]',f).map(el=>[el.dataset.qualityField,el.value])),note:f.elements.note.value});busy=false;closeDialog();await refresh();notify('已保存大豆批次属性，库存组成已更新');});}


function syncPersonnelForm(){const f=document.getElementById('factory-form');if(f?.dataset.kind!=='employee')return;const management=f.elements.employee_type.value==='management',group=f.elements.group_id;group.required=!management;group.closest('label').hidden=management;if(management)group.value='';if(f.elements.salary_mode){const annual=f.elements.salary_mode.value==='annual';for(const [key,on] of [['annual_salary',annual],['monthly_salary',!annual]]){const input=f.elements[key];input.disabled=!on;input.required=on;input.closest('label').hidden=!on;}}}
document.addEventListener('change',e=>{if(e.target.id==='attendance-person-type'){attendanceType=e.target.value;render();}if(e.target.closest('#factory-form')&&['employee_type','salary_mode'].includes(e.target.name)){const f=e.target.form;if(e.target.name==='employee_type'&&f.elements.salary_category)f.elements.salary_category.value=e.target.value==='management'?'wages-management':'wages-production';syncPersonnelForm();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-person-attendance-fill]');if(!b)return;collectAttendanceEditor();const ids=new Set([...document.querySelectorAll('[data-attendance-person]')].map(r=>r.dataset.attendancePerson));for(const entry of attendanceEditor.entries)if(ids.has(entry.employee_id)&&(!entry.status||entry.status==='unrecorded'))entry.status='full';paintAttendanceEditor();});
